/* Geography: 102 questions, 5 rabbit holes. Generated by question-sources/build_questions.js */
(window.TRIVIA_TOPICS = window.TRIVIA_TOPICS || {})["geography"] = {
  questions: [
    {"id":"geography-001","q":"What is the capital city of Canada?","c":["Ottawa","Toronto","Vancouver","Montreal"],"skill":"canada","why":"Ottawa, Ontario — where Parliament is!","hint":"It's in Ontario, and it's NOT the biggest city. Its NHL team is the Senators.","deeper":[{"t":"mc","k":"more","q":"Ottawa is in which province?","c":["Ontario","Quebec","Manitoba","Alberta"],"why":"Ontario — right across the river from Quebec."},{"t":"talk","k":"more","q":"Toronto is bigger, so why might a country pick a capital that ISN'T its biggest city?","peek":"Fairness/compromise (Ottawa sits between English and French Canada), safety, location. Any good reason counts.","clue":"Ottawa is right on the border between Ontario and Quebec. Why might that be fair?"}]},
    {"id":"geography-002","q":"How many provinces does Canada have?","c":["10","13","7","50"],"skill":"canada","why":"10 provinces and 3 territories!","hint":"It's the same as the number of fingers you have.","deeper":[{"t":"mc","k":"more","q":"How many territories does Canada have?","c":["3","10","1","5"],"why":"3: Yukon, Northwest Territories and Nunavut."},{"t":"mc","k":"more","q":"Which is Canada's BIGGEST province or territory by area?","c":["Nunavut","Ontario","Prince Edward Island","Nova Scotia"],"why":"Nunavut! It's enormous — but only about 40,000 people live there."}]},
    {"id":"geography-003","q":"What is the biggest ocean on Earth?","c":["Pacific","Atlantic","Arctic","Indian"],"skill":"world","why":"The Pacific — it's bigger than all the land on Earth put together!","hint":"It's the ocean beside British Columbia.","deeper":[{"t":"mc","k":"more","q":"How many oceans touch Canada?","c":["3","1","2","5"],"why":"3: Pacific (west), Atlantic (east) and Arctic (north)!"},{"t":"talk","k":"more","q":"Canada's motto means \"From sea to sea.\" Look at a map in your head — why is that a good motto?","peek":"Canada stretches from the Atlantic to the Pacific (and the Arctic too).","clue":"Which ocean is on the west side of Canada, and which is on the east?"}]},
    {"id":"geography-004","q":"How many continents are there?","c":["7","5","10","3"],"skill":"world","why":"7: North America, South America, Europe, Asia, Africa, Australia/Oceania and Antarctica.","hint":"Same as the number of days in a week!","deeper":[{"t":"mc","k":"more","q":"Which continent is the coldest and covered in ice?","c":["Antarctica","Africa","Europe","Australia"],"why":"Antarctica, at the South Pole!"},{"t":"talk","k":"more","q":"Penguins live in the far south and polar bears live in the far north (the Arctic). Why don't they meet in the wild?","peek":"They live at opposite ends of the Earth — too far apart, separated by warm oceans/places.","clue":"How far is the North Pole from the South Pole? What's in between?"}]},
    {"id":"geography-005","q":"Which country is right next door to Canada, to the south?","c":["United States","Mexico","Brazil","Russia"],"skill":"canada","why":"The United States! The Canada–US border is the longest border between two countries in the world.","hint":"Its flag has stars and stripes.","deeper":[{"t":"mc","k":"more","q":"The border between Canada and the US is the world's ___ border between two countries.","c":["Longest","Shortest","Coldest","Newest"],"why":"Longest — about 8,900 km!"},{"t":"mc","k":"more","q":"Which US state shares a border with Yukon and British Columbia?","c":["Alaska","Florida","Texas","Hawaii"],"why":"Alaska! It borders the Yukon and British Columbia."}]},
    {"id":"geography-006","q":"How many Great Lakes are there?","c":["5","3","7","10"],"skill":"canada","why":"5! Remember HOMES: Huron, Ontario, Michigan, Erie, Superior.","hint":"Remember the word HOMES — one lake for each letter!","deeper":[{"t":"mc","k":"more","q":"Which Great Lake is the biggest?","c":["Lake Superior","Lake Erie","Lake Ontario","Lake Huron"],"why":"Lake Superior — 'superior' even means 'better/bigger'!"},{"t":"mc","k":"more","q":"Which Great Lake is the ONLY one completely inside the United States (not touching Canada)?","c":["Lake Michigan","Lake Ontario","Lake Superior","Lake Erie"],"why":"Lake Michigan is all in the US. The other four are shared with Canada."}]},
    {"id":"geography-007","q":"What is the tallest mountain in the world?","c":["Mount Everest","Mount Logan","Mount Kilimanjaro","Blue Mountain"],"skill":"world","why":"Mount Everest in Asia — almost 8,850 metres tall!","hint":"It's in the Himalaya mountains in Asia, and its name starts with E.","deeper":[{"t":"mc","k":"more","q":"What is the tallest mountain in Canada?","c":["Mount Logan (Yukon)","Mount Everest","Whistler","CN Tower"],"why":"Mount Logan in the Yukon — almost 6,000 metres!"},{"t":"talk","k":"more","q":"Mountain tops are closer to the Sun, so why is it COLDER up there and often snowy?","peek":"The air is thinner up high and holds less heat; the Sun's tiny bit closer doesn't matter.","clue":"Is there more air or less air way up high? Air acts like a blanket..."}]},
    {"id":"geography-008","q":"Which way does a compass needle point?","c":["North","South","Up","To the nearest Tim Hortons"],"skill":"maps","why":"North! That's how people find their way.","hint":"It points toward the North Pole, where Santa lives!","deeper":[{"t":"mc","k":"whatif","q":"If you face north, which direction is your RIGHT hand pointing?","c":["East","West","South","Down"],"why":"East! Remember 'Never Eat Soggy Waffles' — North, East, South, West going clockwise."},{"t":"mc","k":"more","q":"The Sun rises in the...","c":["East","West","North","South"],"why":"East! And it sets in the west."},{"t":"talk","k":"whatif","q":"If it's morning and the Sun is out your car window, which direction might we be driving? How do you know?","peek":"Uses that the Sun rises in the east (if sun is ahead we're heading east, etc.). Reasoning is what counts.","clue":"Where does the Sun rise? Is it in front, behind, or to the side of the car?"}]},
    {"id":"geography-009","q":"What is the biggest country in the world by area?","c":["Russia","Canada","China","USA"],"skill":"world","why":"Russia is the biggest, and Canada is #2!","hint":"It's Canada's neighbour across the Arctic Ocean.","deeper":[{"t":"mc","k":"more","q":"Which country is the 2nd biggest in the world by area?","c":["Canada","Brazil","Australia","India"],"why":"Canada! It's huge."},{"t":"talk","k":"more","q":"Canada is huge but has fewer people than many smaller countries. Why do so few people live in the far north?","peek":"Very cold, long dark winters, hard to farm/build, far from cities.","clue":"What's the weather like up north? Could you grow a garden there?"}]},
    {"id":"geography-010","q":"Niagara Falls is on the border between Ontario and which US state?","c":["New York","California","Florida","Texas"],"skill":"maps","why":"New York! Half the falls are in Canada and half in the US.","hint":"It's a state with the same name as a very famous big city.","deeper":[{"t":"mc","k":"more","q":"The Niagara River flows from Lake Erie into Lake...?","c":["Ontario","Superior","Michigan","Huron"],"why":"Lake Ontario! The water drops over the falls on the way."},{"t":"talk","k":"more","q":"Lots of electricity is made at Niagara Falls. How could falling water make electricity?","peek":"Rushing water spins turbines/wheels connected to generators.","clue":"Have you seen a water wheel or a pinwheel spin? What could that spinning power?"}]},
    {"id":"geography-011","q":"What is the capital of British Columbia?","c":["Victoria","Vancouver","Kelowna","Whistler"],"skill":"canada","why":"Victoria, on Vancouver Island! Vancouver is BC's biggest city, but not the capital.","hint":"It's on an island, and shares its name with a famous queen.","deeper":[{"t":"mc","k":"more","q":"Victoria is on which island?","c":["Vancouver Island","PEI","Baffin Island","Newfoundland"],"why":"Vancouver Island — confusing, right?"},{"t":"talk","k":"why","q":"Why do you think so many people mix up Vancouver and Victoria?","peek":"Vancouver is bigger and more famous; Vancouver Island has Victoria on it.","clue":"Which one is bigger and has the NHL team?"}]},
    {"id":"geography-012","q":"What is the capital of Alberta?","c":["Edmonton","Calgary","Banff","Red Deer"],"skill":"canada","why":"Edmonton! Calgary is Alberta's biggest city.","hint":"It's the home of the Oilers.","deeper":[{"t":"mc","k":"more","q":"Which famous mountain town is in Alberta?","c":["Banff","Whistler","Niagara-on-the-Lake","Gander"],"why":"Banff, in the Rocky Mountains!"},{"t":"talk","k":"more","q":"Calgary and Edmonton are rival cities. What could make two cities in the same province rivals?","peek":"Sports teams, size, competing for attention/jobs.","clue":"Think of their hockey teams…"}]},
    {"id":"geography-013","q":"What is the capital of Nova Scotia?","c":["Halifax","Sydney","Moncton","Truro"],"skill":"canada","why":"Halifax, a port city on the Atlantic Ocean!","hint":"It's the big port city that helped after the Titanic sank.","deeper":[{"t":"mc","k":"more","q":"'Nova Scotia' means 'New ___' in Latin.","c":["Scotland","Ocean","France","Canada"],"why":"New Scotland! Many settlers came from Scotland."},{"t":"talk","k":"why","q":"Why would a city on the ocean become an important port?","peek":"Ships bring and take goods/people; fishing; trade.","clue":"How did goods travel across oceans long ago?"}]},
    {"id":"geography-014","q":"What is the capital of Quebec?","c":["Quebec City","Montreal","Gatineau","Laval"],"skill":"canada","why":"Quebec City! Montreal is the biggest city in Quebec.","hint":"It has the same name as the province.","deeper":[{"t":"mc","k":"more","q":"Most people in Quebec speak which language at home?","c":["French","English","Spanish","Italian"],"why":"French!"},{"t":"talk","k":"why","q":"Why might it be useful to learn both English and French in Canada?","peek":"Both official languages; talk with more people; jobs; travel.","clue":"What are Canada's two official languages?"}]},
    {"id":"geography-015","q":"What is the capital of Manitoba?","c":["Winnipeg","Brandon","Churchill","Regina"],"skill":"canada","why":"Winnipeg! It's right near the middle of North America.","hint":"Its NHL team is the Jets.","deeper":[{"t":"mc","k":"more","q":"The town of Churchill, Manitoba, is famous for…","c":["Polar bears","Palm trees","Pyramids","Volcanoes"],"why":"Polar bears! It's called the Polar Bear Capital of the World."},{"t":"talk","k":"why","q":"Why might polar bears gather near Churchill in the fall?","peek":"Waiting for Hudson Bay to freeze so they can hunt seals on the ice.","clue":"Where do polar bears hunt seals?"}]},
    {"id":"geography-016","q":"What is the capital of Saskatchewan?","c":["Regina","Saskatoon","Moose Jaw","Winnipeg"],"skill":"canada","why":"Regina! Saskatoon is the largest city.","hint":"It's a Latin word for 'queen'.","deeper":[{"t":"mc","k":"more","q":"Saskatchewan is famous for growing lots of…","c":["Wheat and other grains","Bananas","Coffee","Pineapples"],"why":"Wheat and other grains — it's a Prairie province!"},{"t":"talk","k":"more","q":"The Prairies are very flat. Why is flat land good for big farms?","peek":"Easy to plant and harvest with big machines; lots of sunlight.","clue":"Would it be easy to drive a giant tractor up a mountain?"}]},
    {"id":"geography-017","q":"What is the capital of Newfoundland and Labrador?","c":["St. John's","Gander","Corner Brook","Halifax"],"skill":"canada","why":"St. John's — one of the oldest cities in North America, with colourful 'jellybean' houses!","hint":"Its name has a saint in it.","deeper":[{"t":"mc","k":"more","q":"Cape Spear near St. John's is the most ___ point in North America.","c":["Easterly","Westerly","Northerly","Southerly"],"why":"Easterly! People go there to see the earliest sunrise in North America."},{"t":"talk","k":"more","q":"Newfoundland has its own time zone, 30 minutes ahead of Atlantic time. Why might the most eastern place get the sun first?","peek":"Earth spins west to east, so the east sees sunrise first.","clue":"Which way does the Sun come up from?"}]},
    {"id":"geography-018","q":"What is the capital of Prince Edward Island?","c":["Charlottetown","Summerside","Fredericton","Halifax"],"skill":"canada","why":"Charlottetown! A big meeting there in 1864 helped lead to Confederation.","hint":"Its name has a girl's name in it: Charlotte!","deeper":[{"t":"mc","k":"more","q":"PEI is famous as the home of which story character?","c":["Anne of Green Gables","Harry Potter","Paddington","Peter Pan"],"why":"Anne of Green Gables, by Lucy Maud Montgomery!"},{"t":"mc","k":"more","q":"PEI is connected to New Brunswick by a long bridge called the…","c":["Confederation Bridge","Golden Gate","Lions Gate","Tower Bridge"],"why":"The Confederation Bridge — about 13 km long!"}]},
    {"id":"geography-019","q":"What is the capital of New Brunswick?","c":["Fredericton","Moncton","Saint John","Halifax"],"skill":"canada","why":"Fredericton!","hint":"It starts with 'Fred'.","deeper":[{"t":"mc","k":"more","q":"New Brunswick is Canada's only officially ___ province.","c":["Bilingual (English and French)","Spanish-speaking","Silent","Island"],"why":"Bilingual — English and French!"},{"t":"talk","k":"whatif","q":"If a province has two official languages, what things might be written in both?","peek":"Signs, government forms, school materials, packages.","clue":"What signs do you see on the road?"}]},
    {"id":"geography-020","q":"What is the capital of Nunavut?","c":["Iqaluit","Yellowknife","Whitehorse","Churchill"],"skill":"canada","why":"Iqaluit! Its name means 'place of many fish' in Inuktitut.","hint":"It starts with 'Iq'.","deeper":[{"t":"mc","k":"more","q":"Yellowknife is the capital of…","c":["Northwest Territories","Yukon","Nunavut","Alberta"],"why":"The Northwest Territories!"},{"t":"mc","k":"more","q":"Whitehorse is the capital of…","c":["Yukon","Nunavut","Northwest Territories","BC"],"why":"Yukon!"}]},
    {"id":"geography-021","q":"Which is Canada's SMALLEST province?","c":["Prince Edward Island","Nova Scotia","New Brunswick","Quebec"],"skill":"canada","why":"Prince Edward Island! You can drive across it in a few hours.","hint":"It's an island with red sand beaches.","deeper":[{"t":"mc","k":"more","q":"PEI's beaches and soil are famous for being which colour?","c":["Red","Purple","Black","White"],"why":"Red — from iron in the soil!"},{"t":"talk","k":"more","q":"PEI grows lots of potatoes. Why might an island be a good place to farm?","peek":"Rich soil, mild ocean climate, lots of rain.","clue":"What does a farm need?"}]},
    {"id":"geography-022","q":"Which is Canada's LARGEST province by area?","c":["Quebec","Ontario","British Columbia","Alberta"],"skill":"canada","why":"Quebec! (Nunavut is bigger, but it's a territory, not a province.)","hint":"It's the province where most people speak French.","deeper":[{"t":"mc","k":"more","q":"Which province has the most PEOPLE?","c":["Ontario","Quebec","PEI","Saskatchewan"],"why":"Ontario!"},{"t":"talk","k":"more","q":"Quebec is biggest by area but Ontario has more people. How can that be?","peek":"Much of Quebec is northern forest/tundra with few people; Ontario has many big cities.","clue":"Do people spread out evenly across a province?"}]},
    {"id":"geography-023","q":"Which province has NO ocean coastline?","c":["Saskatchewan","British Columbia","Nova Scotia","Newfoundland and Labrador"],"skill":"canada","why":"Saskatchewan! (Alberta is the other landlocked province.)","hint":"It's a Prairie province right in the middle of the country.","deeper":[{"t":"mc","k":"more","q":"Which other province is landlocked?","c":["Alberta","Manitoba","Ontario","Quebec"],"why":"Alberta! Manitoba and Ontario touch Hudson Bay."},{"t":"talk","k":"more","q":"Saskatchewan has no ocean, but has 100,000 lakes. What do people there do for summer fun?","peek":"Swimming, fishing, boating, cottages at lakes.","clue":"Where do you go swimming if there's no ocean?"}]},
    {"id":"geography-024","q":"The huge bay in north-central Canada is called…","c":["Hudson Bay","Fundy Bay","Bay of Toronto","Pacific Bay"],"skill":"canada","why":"Hudson Bay — named after explorer Henry Hudson.","hint":"Named after an explorer, and a famous old company shares its name.","deeper":[{"t":"mc","k":"more","q":"Which province does NOT touch Hudson Bay?","c":["Alberta","Manitoba","Ontario","Quebec"],"why":"Alberta!"},{"t":"talk","k":"whatif","q":"Hudson Bay freezes in winter. How would that change life for the polar bears and seals there?","peek":"Bears can walk on ice to hunt seals; seals need breathing holes.","clue":"Where do polar bears hunt?"}]},
    {"id":"geography-025","q":"The CN Tower is in which city?","c":["Toronto","Ottawa","Montreal","Calgary"],"skill":"canada","why":"Toronto! It's 553 metres tall and was the world's tallest free-standing structure for over 30 years.","hint":"It's in Canada's biggest city.","deeper":[{"t":"mc","k":"more","q":"The CN Tower has a glass floor. Why is it so exciting?","c":["You can look straight down hundreds of metres","It's made of ice","It moves","It's a trampoline"],"why":"You can look straight down — eek!"},{"t":"talk","k":"why","q":"Why would they build a super tall tower in the first place?","peek":"For TV/radio antennas to send signals farther; also tourism.","clue":"Do signals travel better from high up or low down?"}]},
    {"id":"geography-026","q":"The Rocky Mountains are in which two provinces?","c":["British Columbia and Alberta","Ontario and Quebec","Nova Scotia and PEI","Manitoba and Saskatchewan"],"skill":"canada","why":"BC and Alberta! The Rockies form much of the border between them.","hint":"Think of the western provinces with Banff and Jasper.","deeper":[{"t":"mc","k":"more","q":"Banff and Jasper are famous…","c":["National parks","Hockey teams","Islands","Deserts"],"why":"National parks in the Rockies!"},{"t":"talk","k":"more","q":"When you drive from the Prairies toward the Rockies, how does the land change?","peek":"Flat → foothills → tall mountains.","clue":"What do you see first: hills or flat land?"}]},
    {"id":"geography-027","q":"The Bay of Fundy, between New Brunswick and Nova Scotia, has the world's highest…","c":["Tides","Waterfalls","Mountains","Icebergs"],"skill":"canada","why":"Tides! The water can rise and fall about 16 metres — as tall as a 5-storey building.","hint":"The ocean water goes up and down there more than anywhere else.","deeper":[{"t":"mc","k":"more","q":"What mostly causes tides?","c":["The Moon's gravity","Wind only","Fish","Boats"],"why":"The Moon's pull on the oceans!"},{"t":"talk","k":"more","q":"At the Bay of Fundy, you can walk on the ocean floor at low tide. Why must you be careful?","peek":"The tide comes back in fast and you could get trapped.","clue":"What happens a few hours later?"}]},
    {"id":"geography-028","q":"The flat Prairie provinces grow lots of…","c":["Wheat","Bananas","Rice","Coconuts"],"skill":"canada","why":"Wheat! The Prairies are sometimes called Canada's 'breadbasket'.","hint":"It's a grain used to make bread.","deeper":[{"t":"mc","k":"more","q":"Which is NOT a Prairie province?","c":["Ontario","Alberta","Saskatchewan","Manitoba"],"why":"Ontario! The Prairies are Alberta, Saskatchewan and Manitoba."},{"t":"talk","k":"why","q":"Why would they call the Prairies a 'breadbasket'?","peek":"They grow huge amounts of wheat, which makes bread for Canada and the world.","clue":"What is bread made from?"}]},
    {"id":"geography-029","q":"What is the longest river in Canada?","c":["Mackenzie River","St. Lawrence River","Niagara River","Red River"],"skill":"canada","why":"The Mackenzie River in the Northwest Territories — over 4,000 km long!","hint":"It flows north to the Arctic Ocean, and its name starts with Mac.","deeper":[{"t":"mc","k":"more","q":"The Mackenzie River flows into which ocean?","c":["Arctic","Atlantic","Pacific","Indian"],"why":"The Arctic Ocean!"},{"t":"talk","k":"more","q":"Most rivers in North America flow south or east. Why might a river flow north?","peek":"Water flows downhill — the land slopes down to the north there.","clue":"Does water flow uphill or downhill?"}]},
    {"id":"geography-030","q":"What is the capital of the United States?","c":["Washington, D.C.","New York City","Los Angeles","Chicago"],"skill":"world","why":"Washington, D.C.! New York is the biggest city.","hint":"It's named after the first US president.","deeper":[{"t":"mc","k":"more","q":"The US leader is called the…","c":["President","Prime Minister","King","Mayor"],"why":"The President! Canada has a Prime Minister."},{"t":"talk","k":"more","q":"Canada's capital (Ottawa) and the US capital are both NOT their biggest cities. Why might countries choose a smaller city?","peek":"Compromise between regions, safety, neutral ground.","clue":"Why might picking the biggest city upset other cities?"}]},
    {"id":"geography-031","q":"What is the capital of France?","c":["Paris","Lyon","Montreal","Rome"],"skill":"world","why":"Paris! Home of the Eiffel Tower.","hint":"The Eiffel Tower is there.","deeper":[{"t":"mc","k":"more","q":"Which Canadian province has the most French speakers?","c":["Quebec","Alberta","BC","Nunavut"],"why":"Quebec — French settlers came from France long ago."},{"t":"talk","k":"why","q":"Why do so many people in Quebec speak French?","peek":"Early settlers came from France and kept their language and culture.","clue":"Where did Champlain and Cartier come from?"}]},
    {"id":"geography-032","q":"What is the capital of the United Kingdom?","c":["London","Ottawa","Dublin","Edinburgh"],"skill":"world","why":"London! There's also a London in Ontario.","hint":"It shares its name with a city in Ontario!","deeper":[{"t":"mc","k":"why","q":"Why does Ontario have cities like London and Cambridge?","c":["Settlers named them after places back home","Random names","They're twins","They were moved from England"],"why":"Settlers from Britain named new towns after places back home."},{"t":"talk","k":"whatif","q":"If you moved to a new planet, what would you name your town and why?","peek":"Any name with a reason.","clue":"Would you name it after home?"}]},
    {"id":"geography-033","q":"What is the capital of Japan?","c":["Tokyo","Beijing","Seoul","Osaka"],"skill":"world","why":"Tokyo — one of the biggest cities in the world!","hint":"It starts with T.","deeper":[{"t":"mc","k":"more","q":"Japan is made up of many…","c":["Islands","Deserts","Provinces like Canada's","Lakes"],"why":"Islands — thousands of them!"},{"t":"talk","k":"more","q":"Japan is crowded and has lots of mountains. Where do you think most people live?","peek":"Flat land along coasts and valleys.","clue":"Is it easy to build cities on steep mountains?"}]},
    {"id":"geography-034","q":"In which country do kangaroos and koalas live in the wild?","c":["Australia","Canada","India","Brazil"],"skill":"world","why":"Australia!","hint":"It's a country that is also a continent, 'down under'.","deeper":[{"t":"mc","k":"more","q":"When it's winter in Canada, what season is it in Australia?","c":["Summer","Winter","Fall","Spring"],"why":"Summer! Australia is in the Southern Hemisphere, so seasons are flipped."},{"t":"talk","k":"whatif","q":"Imagine Christmas at the beach in summer! Why are seasons opposite in Australia?","peek":"Earth's tilt: when the north tilts away from the Sun, the south tilts toward it.","clue":"If one half of Earth tilts toward the Sun, what does the other half do?"}]},
    {"id":"geography-035","q":"The Sahara, the world's biggest hot desert, is on which continent?","c":["Africa","Asia","Australia","South America"],"skill":"world","why":"Africa! It's about as big as the whole United States.","hint":"It's the same continent as Egypt and its pyramids.","deeper":[{"t":"mc","k":"more","q":"Tricky! The biggest desert of ALL (counting cold ones) is…","c":["Antarctica","The Sahara","Alberta","The Gobi"],"why":"Antarctica! A desert means very little rain or snow falls — not that it's hot."},{"t":"talk","k":"more","q":"Antarctica is covered in ice. How can it be a desert?","peek":"Deserts are defined by very low precipitation, not heat.","clue":"What makes a place a desert — heat or lack of rain?"}]},
    {"id":"geography-036","q":"Most of the Amazon rainforest is in which country?","c":["Brazil","Canada","Egypt","Australia"],"skill":"world","why":"Brazil! The Amazon is the biggest rainforest in the world.","hint":"It's the biggest country in South America.","deeper":[{"t":"mc","k":"more","q":"People in Brazil mainly speak…","c":["Portuguese","Spanish","French","English"],"why":"Portuguese!"},{"t":"talk","k":"more","q":"The Amazon is called 'the lungs of the planet'. Why?","peek":"Its trees make lots of oxygen and take in carbon dioxide.","clue":"What do trees give off that we breathe?"}]},
    {"id":"geography-037","q":"Which country is shaped like a boot?","c":["Italy","Canada","Japan","Chile"],"skill":"world","why":"Italy! It even looks like it's kicking a ball (the island of Sicily).","hint":"It's the home of pizza and pasta.","deeper":[{"t":"mc","k":"more","q":"The capital of Italy is…","c":["Rome","Venice","Paris","Athens"],"why":"Rome!"},{"t":"talk","k":"whatif","q":"What shape would you say Canada looks like? Use your imagination!","peek":"Any creative answer.","clue":"Picture the map…"}]},
    {"id":"geography-038","q":"The Great Pyramids of Giza are in which country?","c":["Egypt","Mexico","China","Greece"],"skill":"world","why":"Egypt! The Great Pyramid is the only one of the ancient Seven Wonders still standing.","hint":"It's in Africa, by the Nile River.","deeper":[{"t":"mc","k":"more","q":"Which river flows through Egypt?","c":["Nile","Amazon","St. Lawrence","Thames"],"why":"The Nile!"},{"t":"talk","k":"why","q":"Why do you think ancient Egypt grew up along a river in the desert?","peek":"Water for drinking and farming; fertile soil from floods; transport.","clue":"What does everyone need to live?"}]},
    {"id":"geography-039","q":"What are Canada's two official languages?","c":["English and French","English and Spanish","French and Italian","English and Inuktitut"],"skill":"canada","why":"English and French! (Many Indigenous languages are also spoken across Canada.)","hint":"Look at the back of a cereal box!","deeper":[{"t":"mc","k":"more","q":"Which of these is an Indigenous language spoken in Nunavut?","c":["Inuktitut","Portuguese","German","Mandarin"],"why":"Inuktitut!"},{"t":"talk","k":"more","q":"Look at a cereal box or road sign in Canada. Why is the writing in two languages?","peek":"Both official languages, so everyone can read it.","clue":"What two languages do you see?"}]},
    {"id":"geography-040","q":"What is the equator?","c":["An imaginary line around the middle of the Earth","A hot river","A mountain","A country in Africa"],"skill":"maps","why":"An imaginary line around the middle of the Earth, halfway between the North and South Poles.","hint":"It's not real like a road — it's drawn on maps around the middle of the world.","deeper":[{"t":"mc","k":"more","q":"Places near the equator are usually…","c":["Hot all year","Cold all year","Snowy","Dark all day"],"why":"Hot all year!"},{"t":"mc","k":"more","q":"Canada is ___ of the equator.","c":["North","South","On","Under"],"why":"North — way north!"}]},
    {"id":"geography-041","q":"On a map, what does the 'legend' (or key) do?","c":["Explains what the symbols mean","Shows the weather","Tells a story about dragons","Unlocks the map"],"skill":"maps","why":"The legend explains the symbols — like which line is a highway and which dot is a city.","hint":"It's like a dictionary for map pictures.","deeper":[{"t":"mc","k":"more","q":"On a map, blue usually shows…","c":["Water","Roads","Cities","Mountains"],"why":"Water!"},{"t":"talk","k":"whatif","q":"Draw (or describe) a map of your street. What symbols would you put in your legend?","peek":"Any reasonable symbols (house, tree, park, school).","clue":"What's on your street?"}]},
    {"id":"geography-042","q":"On most maps, north is at the…","c":["Top","Bottom","Left","Right"],"skill":"maps","why":"The top! A compass rose shows which way is north.","hint":"Look for an arrow with an 'N' on a map.","deeper":[{"t":"mc","k":"whatif","q":"If north is at the top of a map, where is west?","c":["Left","Right","Top","Bottom"],"why":"Left! Remember 'Never Eat Soggy Waffles' going clockwise."},{"t":"talk","k":"more","q":"Is north REALLY 'up'? Why do you think mapmakers chose to put north at the top?","peek":"It's a choice/convention; it could be any way.","clue":"Is there an 'up' in space?"}]},
    {"id":"geography-043","q":"A globe is a round model of…","c":["The Earth","The Moon","A basketball","The Sun"],"skill":"maps","why":"The Earth! Globes show the real shape of our planet.","hint":"It's a ball-shaped map of our planet.","deeper":[{"t":"mc","k":"why","q":"Why do flat maps stretch some places (like Greenland) to look too big?","c":["You can't flatten a ball without stretching","Greenland is huge","Mistakes","It's on purpose to trick you"],"why":"Flattening a round Earth stretches places near the poles!"},{"t":"talk","k":"more","q":"Try to flatten an orange peel. What happens? How does that explain flat maps?","peek":"It tears/stretches — same problem as flattening the round Earth.","clue":"Can a round peel lie perfectly flat?"}]},
    {"id":"geography-044","q":"A piece of land almost surrounded by water, but attached to land on one side, is a…","c":["Peninsula","Island","Lake","Valley"],"skill":"maps","why":"A peninsula! Nova Scotia is mostly a peninsula.","hint":"It's NOT an island — it's still connected on one side.","deeper":[{"t":"mc","k":"more","q":"Land with water ALL around it is an…","c":["Island","Peninsula","Ocean","Cape"],"why":"An island — like PEI!"},{"t":"talk","k":"more","q":"Look at your hand flat on a table. Which part looks like a peninsula?","peek":"A finger or thumb sticking out.","clue":"What sticks out from your hand?"}]},
    {"id":"geography-045","q":"What is Canada's biggest island?","c":["Baffin Island","Prince Edward Island","Vancouver Island","Cape Breton Island"],"skill":"canada","why":"Baffin Island in Nunavut — the fifth-biggest island in the world!","hint":"It's in the far North, in Nunavut.","deeper":[{"t":"mc","k":"more","q":"Iqaluit, Nunavut's capital, is on which island?","c":["Baffin Island","Vancouver Island","PEI","Newfoundland"],"why":"Baffin Island!"},{"t":"talk","k":"why","q":"Why might fewer people live on Baffin Island than on Vancouver Island?","peek":"Much colder; Arctic; harder to grow food and travel.","clue":"Which island is warmer?"}]},
    {"id":"geography-046","q":"The Trans-Canada Highway goes through…","c":["All 10 provinces","Only Ontario","The USA","Only the territories"],"skill":"maps","why":"All 10 provinces! It's one of the longest national highways in the world — over 7,000 km.","hint":"It's called TRANS-Canada…","deeper":[{"t":"mc","k":"whatif","q":"If you drove 700 km a day, how many days to drive 7,000 km?","c":["10","7","100","70"],"why":"7,000 ÷ 700 = 10 days!","hint":"How many 700s are in 7,000?"},{"t":"talk","k":"whatif","q":"If you drove the whole Trans-Canada Highway, what would you want to see along the way?","peek":"Any places/sights with a reason.","clue":"Think of oceans, mountains, Prairies, cities…"}]},
    {"id":"geography-047","q":"How many time zones does Canada have?","c":["6","1","3","24"],"skill":"maps","why":"6! From Newfoundland Time to Pacific Time.","hint":"More than 5, fewer than 10.","deeper":[{"t":"mc","k":"more","q":"When it's noon in Toronto, what time is it in Vancouver?","c":["9:00 AM","3:00 PM","Noon","Midnight"],"why":"9:00 AM — 3 hours earlier!"},{"t":"talk","k":"why","q":"Why do big countries need more than one time zone?","peek":"The Sun rises at different times across the country.","clue":"Does the Sun rise at the same time in Halifax and Vancouver?"}]},
    {"id":"geography-048","q":"Which ocean is between Canada and Europe?","c":["Atlantic","Pacific","Indian","Arctic"],"skill":"world","why":"The Atlantic Ocean!","hint":"It's the ocean on Canada's EAST coast.","deeper":[{"t":"mc","k":"more","q":"Which ocean is between Canada and Japan?","c":["Pacific","Atlantic","Indian","Southern"],"why":"The Pacific!"},{"t":"talk","k":"whatif","q":"If you flew from Toronto to London, England, which direction would you go?","peek":"East (northeast), across the Atlantic.","clue":"Is England east or west of Canada?"}]},
    {"id":"geography-049","q":"About how much of the Earth's surface is covered by water?","c":["About 70%","About 10%","About 50%","100%"],"skill":"maps","why":"About 70% — that's why Earth is called the 'Blue Planet'!","hint":"Look at a globe — is there more blue or more land?","deeper":[{"t":"mc","k":"more","q":"Most of Earth's water is in the…","c":["Oceans","Lakes","Rivers","Clouds"],"why":"The oceans — salt water!"},{"t":"talk","k":"whatif","q":"If most of Earth is water, why do we need to save fresh water?","peek":"Most is salty; only a tiny bit is fresh and drinkable.","clue":"Can you drink ocean water?"}]},
    {"id":"geography-050","q":"What is the coldest continent?","c":["Antarctica","Europe","North America","Asia"],"skill":"world","why":"Antarctica — the coldest, windiest place on Earth!","hint":"It's at the South Pole.","deeper":[{"t":"mc","k":"more","q":"Who lives in Antarctica?","c":["Scientists, for a while — no permanent towns","Millions of people","Polar bears","Nobody, ever"],"why":"Only scientists, visiting research stations!"},{"t":"talk","k":"whatif","q":"What would you pack for a trip to Antarctica, and why?","peek":"Warm layers, boots, goggles/sunscreen (snow glare), food — with reasons.","clue":"What's the weather like?"}]},
    {"id":"geography-051","q":"Which Canadian city is the biggest?","c":["Toronto","Ottawa","Vancouver","Halifax"],"skill":"canada","why":"Toronto! It's the biggest city in Canada.","hint":"It's the capital of Ontario.","deeper":[{"t":"mc","k":"more","q":"Which is Canada's second-biggest city?","c":["Montreal","Moose Jaw","Iqaluit","Charlottetown"],"why":"Montreal!"},{"t":"talk","k":"why","q":"Why do you think big cities often grow beside lakes, rivers or oceans?","peek":"Water, trade by ship, transportation, food.","clue":"How did people move goods before trucks and trains?"}]},
    {"id":"geography-052","q":"Which country's flag is a white cross on a red square?","c":["Switzerland","Japan","Canada","Brazil"],"skill":"world","why":"Switzerland! It's one of only two square national flags (the other is Vatican City).","hint":"It's a mountain country in Europe famous for chocolate and cheese…","deeper":[{"t":"mc","k":"more","q":"The Red Cross symbol is the Swiss flag with the colours…","c":["Switched","Doubled","Removed","Turned green"],"why":"Red cross on white — swapped!"},{"t":"talk","k":"why","q":"Why do you think the Red Cross symbol was chosen to honour Switzerland?","peek":"Founded there; neutral country.","clue":"Where was the Red Cross started?"}]},
    {"id":"geography-053","q":"Which country's flag is a red circle on white?","c":["Japan","China","Canada","Mexico"],"skill":"world","why":"Japan! The red circle stands for the Sun — Japan is called 'Land of the Rising Sun'.","hint":"The circle is the Sun…","deeper":[{"t":"mc","k":"more","q":"Japan is made up mostly of…","c":["Islands","Deserts","One big flat field","Ice"],"why":"Islands — 4 big ones and thousands of small ones!"},{"t":"talk","k":"whatif","q":"Design a flag for your family. What shape and colour would stand for you?","peek":"Any design with meaning.","clue":"What do you love most?"}]},
    {"id":"geography-054","q":"How many stars are on the flag of the United States?","c":["50","13","100","1"],"skill":"world","why":"50 — one for each state! The 13 stripes are for the first 13 colonies.","hint":"One star for each state…","deeper":[{"t":"mc","k":"more","q":"How many stripes are on the US flag?","c":["13","50","7","10"],"why":"13 stripes!"},{"t":"talk","k":"whatif","q":"If Canada's flag had a symbol for every province and territory, how many would there be?","peek":"13 (10 provinces + 3 territories).","clue":"10 provinces plus how many territories?"}]},
    {"id":"geography-055","q":"Which country's flag is green with a yellow diamond and a blue starry globe?","c":["Brazil","Italy","Ireland","Japan"],"skill":"world","why":"Brazil! The stars show the sky over Rio on the day Brazil became a republic.","hint":"It's the country with most of the Amazon rainforest…","deeper":[{"t":"mc","k":"more","q":"What language do most people in Brazil speak?","c":["Portuguese","Spanish","English","French"],"why":"Portuguese!"},{"t":"talk","k":"why","q":"Why might Brazil's flag be green?","peek":"Forests/nature (and history); any reasoned idea.","clue":"What covers much of Brazil?"}]},
    {"id":"geography-056","q":"Which country's flag shows an eagle on a cactus eating a snake?","c":["Mexico","Spain","USA","Egypt"],"skill":"world","why":"Mexico! It comes from the legend of how the Aztecs chose where to build their city.","hint":"It's Canada's neighbour to the south of the USA…","deeper":[{"t":"mc","k":"more","q":"The capital of Mexico is…","c":["Mexico City","Cancún","Toronto","Lima"],"why":"Mexico City!"},{"t":"talk","k":"why","q":"Why do you think flags often tell old stories?","peek":"To remember history and what makes people proud.","clue":"What story does our maple leaf tell?"}]},
    {"id":"geography-057","q":"The Statue of Liberty in New York was a gift from which country?","c":["France","Canada","England","Japan"],"skill":"world","why":"France gave it in 1886 as a symbol of friendship and freedom.","hint":"A European country famous for the Eiffel Tower…","deeper":[{"t":"mc","k":"why","q":"Why is the Statue of Liberty green?","c":["Its copper skin changed colour in the air","It was painted green","It's made of grass","It's made of jade"],"why":"Copper turns green over time!"},{"t":"talk","k":"more","q":"What is the statue holding up, and what might it mean?","peek":"A torch — lighting the way to freedom.","clue":"What does a torch do in the dark?"}]},
    {"id":"geography-058","q":"'Big Ben', the famous clock bell, is in which city?","c":["London","Paris","Ottawa","New York"],"skill":"world","why":"London, England! Big Ben is really the name of the giant bell inside the tower.","hint":"The capital of the United Kingdom…","deeper":[{"t":"mc","k":"more","q":"The tower that holds Big Ben is now called the…","c":["Elizabeth Tower","Eiffel Tower","Peace Tower","CN Tower"],"why":"Elizabeth Tower!"},{"t":"talk","k":"more","q":"Before phones, why were big clock towers useful in cities?","peek":"Everyone could see/hear the time.","clue":"How did people know the time without watches?"}]},
    {"id":"geography-059","q":"The Taj Mahal, a white marble tomb built by an emperor for his wife, is in which country?","c":["India","Egypt","China","Mexico"],"skill":"world","why":"India! It was built in the 1600s by Shah Jahan.","hint":"A big country in South Asia…","deeper":[{"t":"mc","k":"more","q":"The Taj Mahal is made mostly of…","c":["White marble","Wood","Ice","Plastic"],"why":"Shiny white marble!"},{"t":"talk","k":"more","q":"The Taj Mahal looks different colours at sunrise and sunset. Why?","peek":"Sunlight colour changes during the day.","clue":"What colour is the sky at sunset?"}]},
    {"id":"geography-060","q":"The Sydney Opera House, with roofs shaped like sails, is in which country?","c":["Australia","New Zealand","Italy","Canada"],"skill":"world","why":"Australia! It sits beside Sydney Harbour.","hint":"Kangaroos live in this country too…","deeper":[{"t":"mc","k":"more","q":"Australia's capital city is…","c":["Canberra","Sydney","Melbourne","Perth"],"why":"Canberra — not Sydney!"},{"t":"talk","k":"why","q":"Why do you think the architect made the roof look like sails?","peek":"It's by the harbour with boats.","clue":"What floats in a harbour?"}]},
    {"id":"geography-061","q":"The giant statue of Christ the Redeemer overlooks which city?","c":["Rio de Janeiro, Brazil","Rome, Italy","Lima, Peru","Paris, France"],"skill":"world","why":"Rio de Janeiro, Brazil, from the top of a mountain!","hint":"A big city in Brazil famous for beaches and carnival…","deeper":[{"t":"mc","k":"more","q":"Christ the Redeemer stands with arms…","c":["Stretched wide","Folded","Up high","At its sides"],"why":"Arms open wide!"},{"t":"talk","k":"why","q":"Why put a big statue on top of a mountain?","peek":"Everyone in the city can see it.","clue":"Where can the most people see something?"}]},
    {"id":"geography-062","q":"Mount Kilimanjaro, the tallest mountain in Africa, is in which country?","c":["Tanzania","Egypt","Brazil","Canada"],"skill":"world","why":"Tanzania! It's an old volcano with snow on top, even near the equator.","hint":"An East African country…","deeper":[{"t":"mc","k":"why","q":"Why can there be snow on a mountain near the equator?","c":["It gets colder the higher you go","Snow falls only near the equator","It's fake snow","The Sun can't reach it"],"why":"High up = colder!"},{"t":"talk","k":"whatif","q":"If you climbed a big mountain, what would you notice changing as you go up?","peek":"Colder, fewer trees, thinner air, more wind.","clue":"What happens to plants higher up?"}]},
    {"id":"geography-063","q":"The Great Barrier Reef, the world's biggest coral reef, is off the coast of…","c":["Australia","Canada","Iceland","Chile"],"skill":"world","why":"Australia! It's so big it can be seen from space.","hint":"The same country as kangaroos…","deeper":[{"t":"mc","k":"more","q":"Coral is actually made of…","c":["Tiny animals","Rocks only","Plants","Plastic"],"why":"Tiny animals called polyps!"},{"t":"talk","k":"why","q":"Why might warming oceans be bad for coral?","peek":"Coral bleaching; they lose the algae that feed them.","clue":"What happens to living things when it gets too hot?"}]},
    {"id":"geography-064","q":"The Grand Canyon in the USA was carved over millions of years by…","c":["The Colorado River","A giant glacier","An earthquake","People digging"],"skill":"world","why":"The Colorado River slowly wore away the rock!","hint":"Flowing water, very slowly…","deeper":[{"t":"mc","k":"more","q":"How deep is the Grand Canyon, roughly?","c":["More than 1.6 km (1 mile)","10 metres","100 km","1 metre"],"why":"Over a mile deep!"},{"t":"talk","k":"more","q":"How can water carve rock? Think of a drippy tap.","peek":"Slow erosion over a long time; sand and rocks scrape.","clue":"What happens to a sink under a dripping tap for years?"}]},
    {"id":"geography-065","q":"Which island country is called the 'land of fire and ice' because it has volcanoes AND glaciers?","c":["Iceland","Greenland","Japan","Jamaica"],"skill":"world","why":"Iceland! It even has geysers that shoot hot water into the air.","hint":"Its name has 'ice' in it…","deeper":[{"t":"mc","k":"more","q":"A hot spring that shoots water into the air is a…","c":["Geyser","Glacier","Fjord","Delta"],"why":"A geyser!"},{"t":"talk","k":"more","q":"Iceland uses heat from underground to warm homes. Why is that a good idea?","peek":"Clean, renewable energy.","clue":"Does it run out or make smoke?"}]},
    {"id":"geography-066","q":"The Hawaiian Islands were formed by…","c":["Volcanoes","Glaciers","Rivers","People"],"skill":"world","why":"Volcanoes rising from the ocean floor! Some are still active.","hint":"Hot melted rock from under the sea…","deeper":[{"t":"mc","k":"more","q":"Hawaii is in which ocean?","c":["Pacific","Atlantic","Arctic","Indian"],"why":"Pacific!"},{"t":"talk","k":"whatif","q":"If volcanoes keep erupting, what might happen to Hawaii's land?","peek":"It grows — new land forms.","clue":"Where does the lava go when it cools?"}]},
    {"id":"geography-067","q":"Which river carries the MOST water in the world?","c":["Amazon","Nile","St. Lawrence","Thames"],"skill":"world","why":"The Amazon! It carries more water than the next several biggest rivers combined.","hint":"It flows through the world's biggest rainforest…","deeper":[{"t":"mc","k":"more","q":"The Nile flows north into which sea?","c":["Mediterranean Sea","Red Sea","Caribbean Sea","Black Sea"],"why":"The Mediterranean!"},{"t":"talk","k":"why","q":"Why do you think so much rain falls in the Amazon?","peek":"Warm, wet rainforest, near the equator; trees release water.","clue":"What's the weather like in a rainforest?"}]},
    {"id":"geography-068","q":"About how many countries are in Africa?","c":["54","5","200","12"],"skill":"world","why":"54 — more than any other continent!","hint":"More than 50…","deeper":[{"t":"mc","k":"more","q":"Which is the largest continent?","c":["Asia","Africa","Europe","Australia"],"why":"Asia!"},{"t":"talk","k":"why","q":"Why do you think Africa has so many different languages?","peek":"Many peoples, cultures, long history, huge size.","clue":"How many people and countries are there?"}]},
    {"id":"geography-069","q":"Which is the smallest continent?","c":["Australia (Oceania)","Europe","Antarctica","Asia"],"skill":"world","why":"Australia! It's a country AND a continent.","hint":"It's also a country…","deeper":[{"t":"mc","k":"more","q":"Which continent has no permanent residents, just scientists?","c":["Antarctica","Asia","Australia","Africa"],"why":"Antarctica!"},{"t":"talk","k":"why","q":"Why might it be special to be a whole country and continent at once?","peek":"One country covers the whole land; unique animals.","clue":"Who are Australia's neighbours?"}]},
    {"id":"geography-070","q":"Which country has the most people in the world (since about 2023)?","c":["India","Canada","Brazil","Russia"],"skill":"world","why":"India passed China around 2023 — over 1.4 billion people!","hint":"It's in South Asia, home of the Taj Mahal…","deeper":[{"t":"mc","k":"more","q":"Which country is second for the most people?","c":["China","USA","Australia","Canada"],"why":"China!"},{"t":"talk","k":"more","q":"Canada is huge but has about 40 million people. Why so few for its size?","peek":"Cold north, lots of wilderness; most live near the US border.","clue":"Where do most Canadians live?"}]},
    {"id":"geography-071","q":"Which Alberta city holds a giant rodeo every July called 'The Greatest Outdoor Show on Earth'?","c":["Calgary","Edmonton","Regina","Halifax"],"skill":"canada","why":"The Calgary Stampede!","hint":"The city of the Flames…","deeper":[{"t":"mc","k":"more","q":"A rodeo includes…","c":["Bull riding and chuckwagon races","Ice dancing","Surfing","Skiing"],"why":"Yee-haw!"},{"t":"talk","k":"why","q":"Why do you think cowboys and ranching are important in Alberta's history?","peek":"Big ranches, cattle, prairies.","clue":"What animals live on prairie ranches?"}]},
    {"id":"geography-072","q":"Canada's first national park, created in 1885, is…","c":["Banff","Algonquin","Jasper","Point Pelee"],"skill":"canada","why":"Banff, in the Rocky Mountains of Alberta! It started with hot springs.","hint":"It's in the Rockies, near Calgary…","deeper":[{"t":"mc","k":"more","q":"Lake Louise's water is bright turquoise because of…","c":["Tiny rock dust from glaciers","Blue dye","Swimming pools","Sky paint"],"why":"'Rock flour' from glaciers reflects blue-green light!"},{"t":"talk","k":"why","q":"Why do countries protect land as national parks?","peek":"Protect animals, nature, for future people.","clue":"What would happen if everything were built on?"}]},
    {"id":"geography-073","q":"The city of Montreal is built on…","c":["An island","A volcano","A glacier","A desert"],"skill":"canada","why":"An island in the St. Lawrence River! Mount Royal in the middle gives the city its name.","hint":"Water all around it…","deeper":[{"t":"mc","k":"more","q":"'Montreal' comes from 'Mont Royal', meaning…","c":["Royal mountain","Big river","Cold city","Hockey town"],"why":"Royal mountain!"},{"t":"talk","k":"more","q":"How do people and cars get on and off an island city?","peek":"Bridges, tunnels, ferries.","clue":"What crosses over water?"}]},
    {"id":"geography-074","q":"The 'Thousand Islands' are in which river?","c":["St. Lawrence River","Mackenzie River","Fraser River","Red River"],"skill":"canada","why":"The St. Lawrence! There are actually more than 1,800 islands.","hint":"The same river Jacques Cartier sailed up…","deeper":[{"t":"mc","k":"more","q":"Thousand Island salad dressing is named after…","c":["This area","A thousand chefs","1,000 lettuces","A ship"],"why":"Yum — named after the region!"},{"t":"talk","k":"more","q":"To count as one of the islands, it needs to be above water all year and have at least one tree. Why have a rule?","peek":"So people agree what counts.","clue":"Is a rock that's underwater sometimes an island?"}]},
    {"id":"geography-075","q":"Which is the SMALLEST Great Lake by area?","c":["Lake Ontario","Lake Superior","Lake Huron","Lake Michigan"],"skill":"canada","why":"Lake Ontario! Lake Superior is the biggest.","hint":"Toronto sits on its shore…","deeper":[{"t":"mc","k":"more","q":"Which Great Lake is the deepest?","c":["Lake Superior","Lake Ontario","Lake Erie","Lake Huron"],"why":"Superior — about 400 metres deep at its deepest!"},{"t":"talk","k":"more","q":"A memory trick for the Great Lakes is HOMES. What does each letter stand for?","peek":"Huron, Ontario, Michigan, Erie, Superior.","clue":"H is for…"}]},
    {"id":"geography-076","q":"Quebec's nickname, which appears on old licence plates, is…","c":["La Belle Province","The Rock","Bluenose","The Prairies"],"skill":"canada","why":"'La Belle Province' — the beautiful province!","hint":"It's in French…","deeper":[{"t":"mc","k":"more","q":"Newfoundland's nickname is…","c":["The Rock","The Island of Fire","Big Ben","Turtle"],"why":"The Rock!"},{"t":"talk","k":"whatif","q":"If you made a nickname for your town, what would it be?","peek":"Any creative name with a reason.","clue":"What's special about your town?"}]},
    {"id":"geography-077","q":"Alert, in Nunavut, is famous for being…","c":["The most northern place where people live all year","The hottest town","The biggest city","In the desert"],"skill":"canada","why":"It's the northernmost permanently inhabited place in the world — about 800 km from the North Pole!","hint":"Way up north in Nunavut…","deeper":[{"t":"mc","k":"more","q":"Who lives in Alert?","c":["Military and weather scientists","Penguins","Kangaroos","Nobody"],"why":"A small team of military staff and scientists!"},{"t":"talk","k":"whatif","q":"What would be hardest about living that far north?","peek":"Cold, dark winters, no stores, far from family.","clue":"What do you need to live?"}]},
    {"id":"geography-078","q":"The huge area of ancient rock covering much of Canada is called the…","c":["Canadian Shield","Canadian Sword","Maple Plateau","Great Desert"],"skill":"canada","why":"The Canadian Shield! It has some of the oldest rocks on Earth and tons of lakes.","hint":"It's named after something a knight carries…","deeper":[{"t":"mc","k":"more","q":"The Shield is full of…","c":["Lakes, rocks, forests and minerals","Sand dunes","Palm trees","Volcanoes"],"why":"Lakes and minerals!"},{"t":"talk","k":"why","q":"Why is it hard to farm on the Canadian Shield?","peek":"Thin soil, lots of rock.","clue":"What do plants need under them?"}]},
    {"id":"geography-079","q":"The cold, treeless land in Canada's far north is called…","c":["Tundra","Rainforest","Desert","Savanna"],"skill":"canada","why":"Tundra! The ground is so cold that trees can't grow.","hint":"It's too cold for trees…","deeper":[{"t":"mc","k":"more","q":"Ground that stays frozen all year is called…","c":["Permafrost","Snowflake","Frostbite","Glacier"],"why":"Permafrost!"},{"t":"talk","k":"why","q":"Why might warming temperatures be a problem for permafrost?","peek":"Thawing makes ground soft, buildings sink, releases gases.","clue":"What happens when frozen ground melts?"}]},
    {"id":"geography-080","q":"In the Arctic summer, the Sun stays up all night. This is called the…","c":["Midnight sun","Moon day","Night sun","Polar night"],"skill":"canada","why":"The midnight sun! In winter, the opposite happens — polar night, when it stays dark.","hint":"The Sun is out at midnight…","deeper":[{"t":"mc","k":"why","q":"Why does the Arctic get 24-hour daylight in summer?","c":["The Earth is tilted toward the Sun","The Sun gets bigger","Clouds glow","The Moon shines"],"why":"Earth's tilt!"},{"t":"talk","k":"whatif","q":"How would you fall asleep if it were sunny at bedtime?","peek":"Curtains, eye mask, routine.","clue":"What helps your body know it's bedtime?"}]},
    {"id":"geography-081","q":"The imaginary line at 0° longitude, running through Greenwich, England, is the…","c":["Prime Meridian","Equator","Tropic of Cancer","Arctic Circle"],"skill":"maps","why":"The Prime Meridian! It splits the Earth into east and west.","hint":"'Prime' means first…","deeper":[{"t":"mc","k":"more","q":"The equator splits the Earth into…","c":["North and south","East and west","Land and sea","Day and night"],"why":"North and south!"},{"t":"talk","k":"why","q":"Why do maps need starting lines like the equator and Prime Meridian?","peek":"To measure positions (latitude/longitude).","clue":"How do you describe where a spot is on a big grid?"}]},
    {"id":"geography-082","q":"Canada is in which two hemispheres?","c":["Northern and Western","Southern and Eastern","Northern and Eastern","Southern and Western"],"skill":"maps","why":"Northern (north of the equator) and Western (west of the Prime Meridian)!","hint":"Canada is north of the equator and west of England…","deeper":[{"t":"mc","k":"more","q":"Australia is in which hemispheres?","c":["Southern and Eastern","Northern and Western","Northern and Eastern","Southern and Western"],"why":"Down under and east!"},{"t":"talk","k":"more","q":"When it's summer in Canada, what season is it in Australia? Why?","peek":"Winter — the Southern Hemisphere is tilted away.","clue":"Which half is tilted toward the Sun?"}]},
    {"id":"geography-083","q":"Where a river spreads out into many channels before reaching the sea is called a…","c":["Delta","Canyon","Peak","Glacier"],"skill":"maps","why":"A delta! It's named after the Greek letter Δ, which is a triangle shape.","hint":"It's shaped like a triangle, named after a Greek letter…","deeper":[{"t":"mc","k":"more","q":"Canada's Mackenzie River has a huge delta at the…","c":["Arctic Ocean","Pacific","Atlantic","Lake Ontario"],"why":"The Arctic!"},{"t":"talk","k":"why","q":"Why is soil in a river delta good for farming?","peek":"Rivers drop rich mud/silt.","clue":"What does a river carry with it?"}]},
    {"id":"geography-084","q":"A narrow strip of water connecting two bigger bodies of water is a…","c":["Strait","Bay","Lake","Pond"],"skill":"maps","why":"A strait! Like the Strait of Georgia near Vancouver.","hint":"It sounds like 'straight'…","deeper":[{"t":"mc","k":"more","q":"A group of islands is called an…","c":["Archipelago","Isthmus","Island-o","Atoll only"],"why":"An archipelago — like the Arctic islands!"},{"t":"talk","k":"why","q":"Why might ships use straits as shortcuts?","peek":"Shorter routes between seas.","clue":"Is going around a whole continent fast?"}]},
    {"id":"geography-085","q":"Low land between hills or mountains is called a…","c":["Valley","Peak","Plateau","Cliff"],"skill":"maps","why":"A valley! Rivers often flow through them.","hint":"It's low down between high places…","deeper":[{"t":"mc","k":"more","q":"A flat area raised high up is a…","c":["Plateau","Valley","Canyon","Bay"],"why":"A plateau — like a table!"},{"t":"talk","k":"why","q":"Why do towns often grow in valleys?","peek":"Rivers, flat land, shelter, farming.","clue":"What do people need near them?"}]},
    {"id":"geography-086","q":"On a map, the 'scale' tells you…","c":["How map distances compare to real distances","The temperature","What fish live there","The time"],"skill":"maps","why":"The scale shows that, for example, 1 cm on the map equals 10 km in real life!","hint":"It helps you figure out real distances…","deeper":[{"t":"mc","k":"whatif","q":"If 1 cm = 10 km, then 5 cm on the map is…","c":["50 km","5 km","15 km","500 km"],"why":"5 × 10 = 50 km!"},{"t":"talk","k":"more","q":"Use a map of our trip: how could you estimate how far we have left?","peek":"Measure with fingers/ruler and use the scale.","clue":"How many 'steps' of the scale fit?"}]},
    {"id":"geography-087","q":"GPS on phones and cars works by getting signals from…","c":["Satellites in space","Birds","Underground wires","The Moon"],"skill":"maps","why":"Satellites! Your device listens to several and figures out where you are.","hint":"They're high above the Earth, orbiting…","deeper":[{"t":"mc","k":"more","q":"GPS needs signals from at least how many satellites to find your spot?","c":["4","1","100","0"],"why":"About 4!"},{"t":"talk","k":"more","q":"How did people find their way before GPS?","peek":"Paper maps, compasses, stars, landmarks, asking.","clue":"What did sailors look at at night?"}]},
    {"id":"geography-088","q":"Halfway between north and east is…","c":["Northeast","Southwest","Northwest","Southeast"],"skill":"maps","why":"Northeast! We say north or south first.","hint":"It mixes the two words…","deeper":[{"t":"mc","k":"more","q":"Halfway between south and west is…","c":["Southwest","Northwest","Southeast","Westsouth"],"why":"Southwest!"},{"t":"talk","k":"more","q":"Try it: which way is the car facing now? How could you tell?","peek":"Use the sun, a compass app, road signs.","clue":"Where is the Sun right now?"}]},
    {"id":"geography-089","q":"The Sun sets in the…","c":["West","East","North","South"],"skill":"maps","why":"West! It rises in the east and sets in the west.","hint":"It rises in the east, so it sets in the…","deeper":[{"t":"mc","k":"more","q":"At noon in Canada, the Sun is mostly toward the…","c":["South","North","East","West"],"why":"South!"},{"t":"talk","k":"whatif","q":"If you're watching a sunset, which way are you facing? Which way is north?","peek":"West; north is to your right.","clue":"Point at the sunset — what's on your right?"}]},
    {"id":"geography-090","q":"What is the capital of Germany?","c":["Berlin","Munich","Vienna","Paris"],"skill":"world","why":"Berlin!","hint":"It starts with B…","deeper":[{"t":"mc","k":"more","q":"A wall once split this city in two until 1989. It was the…","c":["Berlin Wall","Great Wall","Hadrian's Wall","Green Monster"],"why":"The Berlin Wall!"},{"t":"talk","k":"whatif","q":"How would you feel if a wall split your town and you couldn't visit family?","peek":"Sad, angry, unfair.","clue":"Who would you miss?"}]},
    {"id":"geography-091","q":"What is the capital of China?","c":["Beijing","Shanghai","Tokyo","Hong Kong"],"skill":"world","why":"Beijing!","hint":"It starts with B and hosted the 2008 and 2022 Olympics…","deeper":[{"t":"mc","k":"more","q":"Beijing hosted both a Summer and a Winter Olympics. Which years?","c":["2008 and 2022","1988 and 2010","2000 and 2020","1976 and 1988"],"why":"2008 Summer and 2022 Winter!"},{"t":"talk","k":"why","q":"Why do so many cities want to host the Olympics?","peek":"Pride, tourists, new buildings, attention.","clue":"What comes to a city during the Olympics?"}]},
    {"id":"geography-092","q":"What is the capital of Egypt?","c":["Cairo","Giza","Alexandria","Nairobi"],"skill":"world","why":"Cairo, on the Nile River!","hint":"Starts with C, on the Nile…","deeper":[{"t":"mc","k":"more","q":"Egypt is on which continent?","c":["Africa","Asia","Europe","South America"],"why":"Africa!"},{"t":"talk","k":"why","q":"Why do most Egyptians live close to the Nile?","peek":"Water in a desert country; farming.","clue":"What's around the Nile?"}]},
    {"id":"geography-093","q":"What is the capital of India?","c":["New Delhi","Mumbai","Agra","Kolkata"],"skill":"world","why":"New Delhi!","hint":"It's 'New' something…","deeper":[{"t":"mc","k":"more","q":"India's biggest city by population is…","c":["Mumbai (or Delhi, depending on how you count)","Agra","Goa","Ottawa"],"why":"Mumbai and Delhi are both huge!"},{"t":"talk","k":"why","q":"Why isn't a country's capital always its biggest city? (Think Canada!)","peek":"Capitals were chosen for history/compromise; e.g., Ottawa vs Toronto.","clue":"Is Ottawa bigger than Toronto?"}]},
    {"id":"geography-094","q":"Canada's tallest mountain, Mount Logan, is in…","c":["Yukon","Alberta","Ontario","Quebec"],"skill":"canada","why":"Yukon! It's about 5,959 metres tall.","hint":"In the far northwest territory, next to Alaska…","deeper":[{"t":"mc","k":"more","q":"Mount Logan is in which mountain range?","c":["Saint Elias Mountains","Laurentians","Appalachians","Rockies"],"why":"The Saint Elias Mountains!"},{"t":"talk","k":"more","q":"Mount Logan has one of the biggest bases of any mountain. Why might a big base matter?","peek":"Very wide and massive; hard to climb; huge.","clue":"Is a wide mountain harder to cross?"}]},
    {"id":"geography-095","q":"The 'Cabot Trail', a famous scenic highway, loops around which island?","c":["Cape Breton Island (Nova Scotia)","Vancouver Island","Baffin Island","Prince Edward Island"],"skill":"canada","why":"Cape Breton Island, Nova Scotia — named after explorer John Cabot!","hint":"It's in Nova Scotia…","deeper":[{"t":"mc","k":"more","q":"Many people on Cape Breton have family roots in…","c":["Scotland","Japan","Brazil","Egypt"],"why":"Scotland — Nova Scotia means 'New Scotland'!"},{"t":"talk","k":"why","q":"Why might people name places after their old homeland?","peek":"Remember home, feel connected.","clue":"Would you miss your home if you moved far?"}]},
    {"id":"geography-096","q":"Which BC island has a city that is the province's capital?","c":["Vancouver Island (Victoria)","Baffin Island","Prince Edward Island","Montreal Island"],"skill":"canada","why":"Vancouver Island — home of Victoria! (The city of Vancouver is on the mainland.)","hint":"The capital is Victoria…","deeper":[{"t":"mc","k":"more","q":"To get from Vancouver to Victoria, many people take a…","c":["Ferry","Train","Bridge","Tunnel"],"why":"A ferry — no bridge!"},{"t":"talk","k":"why","q":"Why might there be no bridge to Vancouver Island?","peek":"Too wide and deep; very expensive.","clue":"How far is it across the water?"}]},
    {"id":"geography-097","q":"Which country has the longest coastline in the world?","c":["Canada","Russia","Australia","Brazil"],"skill":"world","why":"Canada! Thanks to all our Arctic islands, it's the longest by far.","hint":"Think of all the islands up north…","deeper":[{"t":"mc","k":"more","q":"Canada touches how many oceans?","c":["3","1","2","5"],"why":"Atlantic, Pacific and Arctic!"},{"t":"talk","k":"whatif","q":"If you walked Canada's coast at 20 km a day, would you finish in your lifetime?","peek":"No — over 240,000 km would take 30+ years!","clue":"How far is that?"}]},
    {"id":"geography-098","q":"An imaginary line around the Earth at 66.5° north marking where the midnight sun begins is the…","c":["Arctic Circle","Equator","Prime Meridian","Hockey Line"],"skill":"maps","why":"The Arctic Circle! North of it, there's at least one day a year when the Sun never sets.","hint":"It's a circle way up north…","deeper":[{"t":"mc","k":"more","q":"Which Canadian territories reach north of the Arctic Circle?","c":["Yukon, NWT and Nunavut","Only Ontario","None","Only PEI"],"why":"All three territories!"},{"t":"talk","k":"more","q":"Is the Arctic Circle a line you can see on the ground? How do we know where it is?","peek":"No — calculated from Earth's tilt; sometimes marked by signs.","clue":"Is the equator painted on the Earth?"}]},
    {"id":"geography-099","q":"Which Italian city has canals instead of streets, where people ride boats called gondolas?","c":["Venice","Rome","Milan","Toronto"],"skill":"world","why":"Venice! It's built on more than 100 small islands.","hint":"It's in Italy and starts with V…","deeper":[{"t":"mc","k":"more","q":"In Venice, an ambulance or a taxi is usually a…","c":["Boat","Helicopter","Horse","Bike"],"why":"A boat!"},{"t":"talk","k":"whatif","q":"What would be fun and what would be hard about living in a city of canals?","peek":"Boats are fun; flooding, no cars, carrying groceries.","clue":"How would you get to school?"}]},
    {"id":"geography-100","q":"In the Dead Sea, people easily float because the water is very…","c":["Salty","Cold","Shallow","Sweet"],"skill":"world","why":"Salty! The salt makes the water dense, so you bob like a cork.","hint":"Too much of something you put on fries…","deeper":[{"t":"mc","k":"why","q":"Why is it called the 'Dead' Sea?","c":["It's too salty for fish to live in","It's haunted","It never moves","It's dry"],"why":"Almost nothing can live in it!"},{"t":"talk","k":"more","q":"Is it easier to float in the ocean or a lake? Why?","peek":"Ocean — salt water helps you float.","clue":"Which water is saltier?"}]},
    {"id":"geography-101","q":"The Panama Canal lets ships cross between which two oceans without going around South America?","c":["Atlantic and Pacific","Arctic and Indian","Atlantic and Arctic","Pacific and Indian"],"skill":"world","why":"Atlantic and Pacific! It saves ships thousands of kilometres.","hint":"It's a shortcut across Central America…","deeper":[{"t":"mc","k":"more","q":"Ships in the canal are lifted up and down using water 'steps' called…","c":["Locks","Keys","Ramps","Elevators made of rope"],"why":"Locks!"},{"t":"talk","k":"more","q":"Canada's St. Lawrence Seaway also has locks. Why do ships need to be lifted?","peek":"Water levels differ; lakes are higher than the sea.","clue":"Is Lake Ontario at the same height as the ocean?"}]},
    {"id":"geography-102","q":"Mount Everest sits on the border between Nepal and…","c":["China (Tibet)","India","Canada","Japan"],"skill":"world","why":"China (Tibet)! It's about 8,849 metres tall.","hint":"A huge country to the north of Nepal…","deeper":[{"t":"mc","k":"more","q":"Everest is in which mountain range?","c":["The Himalayas","The Rockies","The Andes","The Alps"],"why":"The Himalayas!"},{"t":"talk","k":"more","q":"Everest is still growing a tiny bit each year. How could a mountain grow?","peek":"Plates of the Earth pushing together.","clue":"What happens when two things push into each other?"}]}
  ],
  holes: [
    {"id":"rivers","title":"Rivers & the Water Cycle","emoji":"💧","match":"river|lake|water|ocean|rain|delta|niagara|amazon|nile|mackenzie|st\\. lawrence|great lakes|falls","depth":5,"size":8,"root":{"id":"geography:rivers","k":"more","d":"Where does river water come from?","t":"mc","q":"Rivers get their water from…","c":["Rain, melting snow and springs","Taps","Oceans pushing uphill","Clouds touching the ground"],"why":"Rain and melting snow, all flowing downhill!","next":[{"id":"geography:rivers.0","k":"why","d":"Why do rivers flow to the sea?","t":"mc","q":"Rivers flow toward the ocean because…","c":["Water flows downhill and oceans are lowest","Fish swim that way","The wind pushes","Boats pull it"],"why":"Gravity pulls water downhill!","next":[{"id":"geography:rivers.0.0","k":"whatif","d":"What if it gets back up?","t":"mc","q":"Ocean water warms in the sun and turns into vapour. This is called…","c":["Evaporation","Freezing","Melting","Boiling over"],"why":"Evaporation — then it makes clouds and rain again. The water cycle!","next":[{"id":"geography:rivers.0.0.0","k":"more","d":"Old water?","t":"talk","q":"The water you drink may once have been drunk by a dinosaur! How can that be?","peek":"The same water keeps cycling around Earth for millions of years.","clue":"Does water ever get made new or used up?","next":[{"id":"geography:rivers.0.0.0.0","k":"whatif","d":"Where's the fresh water?","t":"mc","q":"Most of Earth's water is…","c":["Salty ocean water","Fresh lake water","Ice cream","In clouds"],"why":"About 97% is salty! Fresh water is precious.","next":[]}]}]}]},{"id":"geography:rivers.1","k":"more","d":"Canada's water","t":"mc","q":"Canada has more lakes than…","c":["Any other country","Just one country","No countries","Australia only"],"why":"More lakes than any country — millions!","next":[{"id":"geography:rivers.1.0","k":"why","d":"Why so many lakes?","t":"talk","q":"Why do you think Canada has so many lakes? (Hint: ice!)","peek":"Glaciers scraped holes during the Ice Age that filled with water.","clue":"What were giant sheets of ice doing to the land?","next":[]}]},{"id":"geography:rivers.2","k":"whatif","d":"Waterfalls","t":"mc","q":"Niagara Falls slowly moves upstream because…","c":["The water wears away the rock edge","It's on wheels","People push it","It doesn't move"],"why":"Erosion! It used to move about a metre a year before people slowed it down.","next":[]}]}},
    {"id":"mountains","title":"Mountain Makers","emoji":"🏔️","match":"mountain|everest|rock|logan|rockies|kilimanjaro|canyon|valley|glacier|himalaya|plateau|rocky|alberta|banff|volcano|shield|tundra|desert|sahara|land","depth":4,"size":7,"root":{"id":"geography:mountains","k":"more","d":"How do mountains form?","t":"mc","q":"Many big mountains form when…","c":["Pieces of Earth's crust push together","It snows a lot","People pile rocks","Volcanoes only"],"why":"Plates crash and crumple upward — very, very slowly!","next":[{"id":"geography:mountains.0","k":"why","d":"Why so slow?","t":"talk","q":"Plates move about as fast as your fingernails grow. How could that make a mountain taller than a plane flies?","peek":"Tiny bits add up over millions of years.","clue":"How much does a nail grow in a million years?","next":[{"id":"geography:mountains.0.0","k":"whatif","d":"What if you climbed Everest?","t":"mc","q":"At the top of Everest, the air has about…","c":["One-third as much oxygen per breath","Ten times more oxygen","No air at all","Candy floss"],"why":"About a third — climbers often use bottled oxygen!","next":[{"id":"geography:mountains.0.0.0","k":"more","d":"Altitude sickness","t":"talk","q":"Climbers go up slowly and rest for days. Why might going up slowly help?","peek":"The body gets used to thin air (acclimatizes).","clue":"Do you jump into a cold lake fast or slowly?","next":[]}]}]},{"id":"geography:mountains.1","k":"more","d":"Rivers of ice","t":"mc","q":"A glacier is…","c":["A huge, slow river of ice","A frozen hockey rink","A snowman","A type of cloud"],"why":"Glaciers flow downhill, super slowly!","next":[{"id":"geography:mountains.1.0","k":"why","d":"How glaciers carve","t":"mc","q":"Glaciers carve valleys shaped like the letter…","c":["U","V","Z","S"],"why":"U-shaped! Rivers carve V-shaped valleys.","next":[{"id":"geography:mountains.1.0.0","k":"whatif","d":"What if glaciers melt?","t":"talk","q":"Many glaciers are shrinking. What might happen to rivers that get water from them?","peek":"Less water in summer, especially for towns and farms.","clue":"Where does glacier meltwater go?","next":[]}]}]}]}},
    {"id":"compass","title":"Maps, Compasses & Getting Lost","emoji":"🧭","match":"compass|north|south|east|west|map|gps|legend|scale|equator|meridian|hemisphere|direction|globe|capital|city|country|countries|flag|continent|province|border|time zone|highway|language|english|french","depth":5,"size":7,"root":{"id":"geography:compass","k":"more","d":"How does a compass work?","t":"mc","q":"A compass needle points north because…","c":["Earth acts like a giant magnet","It's heavy on one end","The wind blows it","It sees Santa"],"why":"Earth's magnetism pulls the magnetic needle!","next":[{"id":"geography:compass.0","k":"why","d":"Magnetic north moves?","t":"mc","q":"The magnetic North Pole slowly…","c":["Moves around","Stays exactly still forever","Is in Toronto","Is on the Moon"],"why":"It drifts — it's been moving from Canada's Arctic toward Russia!","next":[{"id":"geography:compass.0.0","k":"whatif","d":"What if you had no compass?","t":"talk","q":"What if you got lost without a compass or phone? What clues in nature could help?","peek":"Sun rises east, sets west; the North Star; moss and snow clues aren't reliable.","clue":"Where does the Sun come up?","next":[{"id":"geography:compass.0.0.0","k":"more","d":"The North Star","t":"mc","q":"The North Star (Polaris) is useful because it…","c":["Stays almost still over the North Pole","Is the brightest star","Moves fast","Is the Sun"],"why":"It barely moves, so it shows north!","next":[{"id":"geography:compass.0.0.0.0","k":"why","d":"Find it!","t":"talk","q":"You can find Polaris using the Big Dipper's two 'pointer stars'. Why would sailors love that?","peek":"Navigate at night, find direction without tools.","clue":"How did ships know where to go at night?","next":[]}]}]}]},{"id":"geography:compass.1","k":"more","d":"Flat maps, round Earth","t":"mc","q":"Why do flat world maps make Greenland look huge?","c":["Stretching a round Earth onto flat paper","Greenland is bigger than Africa","Mapmakers love Greenland","It's a mistake"],"why":"Flattening stretches places near the poles!","next":[{"id":"geography:compass.1.0","k":"whatif","d":"Peel an orange!","t":"talk","q":"Try to flatten an orange peel without tearing it. What happens, and what does it teach about maps?","peek":"It tears/stretches — every flat map distorts something.","clue":"Can a round thing lie flat?","next":[]}]}]}},
    {"id":"oceans","title":"Ocean Explorers","emoji":"🌊","match":"ocean|sea|tide|coast|island|pacific|atlantic|arctic|fundy|reef|whale|beach|strait","depth":4,"size":7,"root":{"id":"geography:oceans","k":"more","d":"How deep is the ocean?","t":"mc","q":"The deepest place in the ocean, the Mariana Trench, is about…","c":["11 km deep","100 metres","1 km","As deep as a pool"],"why":"About 11 km — deeper than Everest is tall!","next":[{"id":"geography:oceans.0","k":"why","d":"Why is the deep ocean dark?","t":"mc","q":"Why is it pitch black deep in the ocean?","c":["Sunlight can't reach that deep","It's night all the time","Fish turn off lights","The water is black"],"why":"Light fades quickly with depth!","next":[{"id":"geography:oceans.0.0","k":"whatif","d":"What lives there?","t":"mc","q":"Some deep-sea fish make their own light. This is called…","c":["Bioluminescence","Photosynthesis","Lightning","Reflection"],"why":"Bioluminescence — like fireflies of the sea!","next":[{"id":"geography:oceans.0.0.0","k":"why","d":"Why glow?","t":"talk","q":"Why might a fish in the dark make its own light?","peek":"Attract food, find mates, confuse predators.","clue":"What do you use a flashlight for?","next":[]}]},{"id":"geography:oceans.0.1","k":"more","d":"Squeeze!","t":"talk","q":"Water pressure is so strong in the deep that it could crush a pop can. How do you think submarines survive?","peek":"Very thick, strong round hulls.","clue":"What shape is strongest under squeeze?","next":[]}]},{"id":"geography:oceans.1","k":"more","d":"Why is the ocean salty?","t":"mc","q":"The ocean is salty because…","c":["Rivers carry tiny bits of salt from rocks into it","Fish cry","People dump salt","Whales sweat"],"why":"Rain and rivers wash minerals from rocks into the sea over millions of years!","next":[{"id":"geography:oceans.1.0","k":"whatif","d":"Drink seawater?","t":"talk","q":"What if you were thirsty on a boat — why shouldn't you drink seawater?","peek":"Too much salt makes your body lose even more water.","clue":"What happens when you eat salty chips?","next":[]}]}]}},
    {"id":"north","title":"The Far North","emoji":"❄️","match":"arctic|north|nunavut|yukon|inuit|tundra|permafrost|polar|igloo|iqaluit|alert|midnight|baffin|ice|northern lights|cold|snow|winter|antarctic|penguin|polar","depth":5,"size":7,"root":{"id":"geography:north","k":"more","d":"Polar night","t":"mc","q":"In the far north in winter, some places don't see the Sun for…","c":["Weeks or even months","5 minutes","Never","Every day"],"why":"Polar night can last weeks or months!","next":[{"id":"geography:north.0","k":"why","d":"Why is it dark so long?","t":"mc","q":"Why does the Arctic have long dark winters?","c":["Earth's tilt points the North away from the Sun","The Sun takes a holiday","Clouds block it","Snow eats light"],"why":"Earth's tilt!","next":[{"id":"geography:north.0.0","k":"whatif","d":"What if Earth had no tilt?","t":"talk","q":"What if Earth wasn't tilted at all? What would happen to seasons?","peek":"Hardly any seasons; days about the same length all year.","clue":"What causes summer and winter?","next":[{"id":"geography:north.0.0.0","k":"more","d":"Northern lights","t":"mc","q":"The northern lights are best seen in Canada's…","c":["North, on dark winter nights","Cities at noon","Swimming pools","Deserts"],"why":"Yukon, NWT and Nunavut are some of the best places on Earth!","next":[{"id":"geography:north.0.0.0.0","k":"why","d":"Why different colours?","t":"talk","q":"Aurora can be green, pink or purple. Why might different colours appear?","peek":"Different gases (oxygen, nitrogen) glow different colours at different heights.","clue":"Do different things glow different colours?","next":[]}]}]}]},{"id":"geography:north.1","k":"more","d":"Living on the ice","t":"mc","q":"An Inuit snow house is called an…","c":["Igloo (iglu)","Teepee","Cabin","Castle"],"why":"Iglu means house in Inuktitut!","next":[{"id":"geography:north.1.0","k":"why","d":"Why is snow warm?","t":"talk","q":"An igloo made of snow can be much warmer inside than outside. How can snow keep you warm?","peek":"Snow has trapped air that insulates; body heat stays in.","clue":"What's in a puffy jacket?","next":[]}]}]}}
  ]
};
